//! Alembic design tokens, GENERATED by `cargo xtask tokens` from `design/tokens.json`.
//! Do not edit by hand: change the token file and regenerate (CI runs `tokens --check`).
//! Colours are `0xRRGGBBAA`; dimensions are logical pixels.

/// The semantic colours of one theme.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Palette {
    /// `accent.border`.
    pub accent_border: u32,
    /// `accent.default`: brass: primary action, focus ring, selection, slider fill.
    pub accent_default: u32,
    /// `accent.focusRing`: 3px outer ring on focused inputs.
    pub accent_focus_ring: u32,
    /// `accent.subtle`: active nav item, selected row.
    pub accent_subtle: u32,
    /// `accent.text`.
    pub accent_text: u32,
    /// `bg.base`: window background.
    pub bg_base: u32,
    /// `bg.code`: template editor, secrets.
    pub bg_code: u32,
    /// `bg.overlay`: menus, dialogs, secondary buttons, toasts.
    pub bg_overlay: u32,
    /// `bg.raised`: cards, tables, panels.
    pub bg_raised: u32,
    /// `bg.sidebar`: navigation rail, inset inputs.
    pub bg_sidebar: u32,
    /// `danger.border`.
    pub danger_border: u32,
    /// `danger.default`: cinnabar: stop, kill, revoke, delete.
    pub danger_default: u32,
    /// `danger.subtle`.
    pub danger_subtle: u32,
    /// `danger.text`.
    pub danger_text: u32,
    /// `info.default`: loading, downloading, verifying.
    pub info_default: u32,
    /// `info.subtle`.
    pub info_subtle: u32,
    /// `info.text`.
    pub info_text: u32,
    /// `line.dashed`: read-only / external source outline.
    pub line_dashed: u32,
    /// `line.default`: card borders, track of meters.
    pub line_default: u32,
    /// `line.strong`: input and button borders.
    pub line_strong: u32,
    /// `line.subtle`: table row separators.
    pub line_subtle: u32,
    /// `muted.default`: idle, not loaded, disabled.
    pub muted_default: u32,
    /// `muted.subtle`.
    pub muted_subtle: u32,
    /// `ok.default`: verdigris: running, GPU resident, toggles on.
    pub ok_default: u32,
    /// `ok.subtle`.
    pub ok_subtle: u32,
    /// `ok.text`.
    pub ok_text: u32,
    /// `text.faint`: axis ticks, token names; not for body text.
    pub text_faint: u32,
    /// `text.muted`: labels, captions.
    pub text_muted: u32,
    /// `text.onAccent`.
    pub text_on_accent: u32,
    /// `text.primary`.
    pub text_primary: u32,
    /// `text.secondary`.
    pub text_secondary: u32,
}

