/// A model kind badge: glyph + label + colour on a tint (never colour alone).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct KindToken {
    /// Token key (`chat`, `embeddings`, ...).
    pub key: &'static str,
    /// Glyph drawn before the label.
    pub glyph: &'static str,
    /// Label text.
    pub label: &'static str,
    /// Text and glyph colour.
    pub fg: u32,
    /// Badge background (the foreground at 15 % alpha).
    pub tint: u32,
}

