/// A processor-state pill (Library and Running): dot + label on a background.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ProcessorStateToken {
    /// Token key (`gpu`, `split`, `cpu`, `loading`, `off`).
    pub key: &'static str,
    /// Pill background.
    pub bg: u32,
    /// Label colour.
    pub fg: u32,
    /// Status dot colour.
    pub dot: u32,
    /// Outline, when the pill has one.
    pub border: Option<u32>,
    /// Label template (`{gpu}`, `{cpu}`, `{pct}` are placeholders).
    pub label: &'static str,
}

