/// Font families (embedded, OFL-1.1) and weights.
pub mod font {
    /// UI family (`font.family.ui`).
    pub const UI: &str = "Schibsted Grotesk";
    /// Numbers, sizes, paths, quants, ids (`font.family.mono`).
    pub const MONO: &str = "IBM Plex Mono";
    /// `font.weight.bold`.
    pub const WEIGHT_BOLD: u16 = 700;
    /// `font.weight.medium`.
    pub const WEIGHT_MEDIUM: u16 = 500;
    /// `font.weight.regular`.
    pub const WEIGHT_REGULAR: u16 = 400;
    /// `font.weight.semibold`.
    pub const WEIGHT_SEMIBOLD: u16 = 600;
}

/// Which embedded family a type style uses.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Family {
    /// [`font::UI`].
    Ui,
    /// [`font::MONO`].
    Mono,
}

/// One step of the type scale.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct TypeStyle {
    /// Font family.
    pub family: Family,
    /// Font size in pixels.
    pub size: f32,
    /// Font weight (400 regular .. 700 bold).
    pub weight: u16,
    /// Line height as a multiple of the size.
    pub line_height: f32,
    /// Letter spacing in em.
    pub letter_spacing: f32,
    /// Whether the text is set in capitals.
    pub uppercase: bool,
}

