/// A drop shadow.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Shadow {
    /// Horizontal offset.
    pub offset_x: f32,
    /// Vertical offset.
    pub offset_y: f32,
    /// Blur radius.
    pub blur: f32,
    /// Spread radius.
    pub spread: f32,
    /// Shadow colour.
    pub color: u32,
}

/// `shadow.overlay`: only menus, dialogs, toasts; raised surfaces use a border, no shadow.
pub const SHADOW_OVERLAY: Shadow = Shadow {
    offset_x: 0.0,
    offset_y: 12.0,
    blur: 32.0,
    spread: 0.0,
    color: 0x00000073,
};
